SET NOCOUNT ON;
IF OBJECT_ID('dbo.TelemetryReadings','U') IS NOT NULL DROP TABLE dbo.TelemetryReadings;
IF OBJECT_ID('dbo.InspectionFindings','U') IS NOT NULL DROP TABLE dbo.InspectionFindings;
IF OBJECT_ID('dbo.WorkOrders','U') IS NOT NULL DROP TABLE dbo.WorkOrders;
IF OBJECT_ID('dbo.Projects','U') IS NOT NULL DROP TABLE dbo.Projects;
IF OBJECT_ID('dbo.Customers','U') IS NOT NULL DROP TABLE dbo.Customers;
CREATE TABLE dbo.Customers (CustomerId INT PRIMARY KEY, CustomerName NVARCHAR(200), Sector NVARCHAR(80), Region NVARCHAR(40), OnboardedDate DATE);
CREATE TABLE dbo.Projects (ProjectId INT PRIMARY KEY, CustomerId INT NOT NULL, ProjectName NVARCHAR(220), Status NVARCHAR(40), BudgetUsd BIGINT, SpentUsd BIGINT, StartDate DATE, TargetEndDate DATE, FOREIGN KEY (CustomerId) REFERENCES dbo.Customers(CustomerId));
CREATE TABLE dbo.WorkOrders (WorkOrderId INT PRIMARY KEY, ProjectId INT NOT NULL, Status NVARCHAR(40), Severity NVARCHAR(20), SystemArea NVARCHAR(80), HoursOpen INT, OpenedDate DATE, FOREIGN KEY (ProjectId) REFERENCES dbo.Projects(ProjectId));
CREATE TABLE dbo.InspectionFindings (FindingId INT PRIMARY KEY, WorkOrderId INT NOT NULL, FindingType NVARCHAR(50), Result NVARCHAR(20), Notes NVARCHAR(500), CapturedAt DATETIME2, FOREIGN KEY (WorkOrderId) REFERENCES dbo.WorkOrders(WorkOrderId));
CREATE TABLE dbo.TelemetryReadings (ReadingId INT PRIMARY KEY, ProjectId INT NOT NULL, CapturedAt DATETIME2, MetricName NVARCHAR(80), MetricValue DECIMAL(12,3), HealthState NVARCHAR(20), FOREIGN KEY (ProjectId) REFERENCES dbo.Projects(ProjectId));
